<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import { defaultCrmSettings, crmPages, crmClientLocation, crmDay, parseCrmCsv, crmCsv, type CrmKind } from '../../utils/crm'
import RecordEditor from './RecordEditor.vue'
import Settings from './Settings.vue'
import Funnel from './Funnel.vue'
import Campaigns from './Campaigns.vue'
const route=useRoute()
const props=defineProps<{section:string;recordId?:string;embedded?:boolean}>()
const scope=useCompanyScope(),boot=ref<any>(null),rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),summary=ref<any>(null),reports=ref<any>(null),detail=ref<any>(null)
const editor=ref<any>(null),editorKind=ref<CrmKind>('clients'),view=ref('board'),selected=ref<string[]>([]),bulkOwner=ref(''),dragId=ref('')
const filter=ref<any>({q:'',ownerId:'',source:'',lifecycle:'',leadStatus:'',tag:'',status:'',priority:'',segmentKey:typeof route.query.segmentKey==='string'?route.query.segmentKey:'',pipelineKey:'',archived:'false',minScore:''})
const reportDates=ref({from:'',to:''}),calendarMonth=ref(crmDay().slice(0,7)),segmentName=ref(''),segmentKey=ref('')
const importing=ref(false),importText=ref(''),preview=ref<any>(null),importRows=ref<any[]>([])
const documentPanel=ref(false),documentKind=ref('QUOTE'),documentSearch=ref(''),documentChoices=ref<any[]>([]),documentId=ref('')
const orderPreview=ref<any>(null)
async function showOrder(id:string){await run(async()=>{orderPreview.value=await api('order-summary/'+id)})}
let requestVersion=0,disposed=false
const kind=computed<CrmKind|null>(()=>['clients','segments'].includes(props.section)?'clients':['activities','calendar'].includes(props.section)?'activities':props.section==='accounts'?'accounts':props.section==='deals'?'deals':null)
watch(()=>route.query.segmentKey,value=>{if(props.section==='segments'){segmentKey.value=typeof value==='string'?value:'';if(boot.value)selectSegment()}else{filter.value.segmentKey=typeof value==='string'?value:'';if(boot.value)search()}})
const settings=computed(()=>boot.value?.settings||defaultCrmSettings()),actor=computed(()=>boot.value?.actor||{userId:'',manager:false})
const title=computed(()=>props.recordId?detail.value?.record?.name||'Record details':crmPages.find(([path])=>(path||'overview')===props.section)?.[1]||'CRM')
const pageSize=computed(()=>props.section==='calendar'?200:props.section==='deals'&&view.value==='board'?100:30)
const pipeline=computed(()=>settings.value.pipelines.find((p:any)=>p.key===filter.value.pipelineKey)||settings.value.pipelines[0])
const canManage=computed(()=>!!actor.value.manager),locked=computed(()=>saving.value||!!editor.value||importing.value||documentPanel.value)
watch(locked,value=>{scope.busy.value=value})
const api=(path:string,options:any={})=>scope.fetch('/api/crm/'+path,{...options,retry:0}) as Promise<any>
const link=(path:string)=>path==='/client'?crmClientLocation({entryCompany:scope.companyId.value}):({path,query:{entryCompany:scope.companyId.value}})
const recordLink=(type:string,id:string)=>type==='clients'?crmClientLocation({entryCompany:scope.companyId.value,crmClient:id}):link('/crm/'+type+'/'+id)
const money=(value:any)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:boot.value?.currency||'INR',maximumFractionDigits:2}).format(Number(value)||0)
const date=(value:any)=>value?new Date(String(value).length===10?value+'T12:00:00Z':value).toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata'}):'—'
const time=(value:any)=>value?new Date(value).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}):'No due date'
const canEdit=(row:any)=>!row.archived&&(canManage.value||row.ownerId===actor.value.userId||row.createdBy===actor.value.userId||(!row.ownerId&&!row.createdBy&&kind.value==='clients'))
const selectedRows=computed(()=>rows.value.filter(r=>selected.value.includes(r.id)))
const allSelected=computed(()=>rows.value.length>0&&selected.value.length===rows.value.length)
const calendarDays=computed(()=>{const start=new Date(calendarMonth.value+'-01T12:00:00Z');const first=new Date(+start-((start.getUTCDay()+6)%7)*86400000);return Array.from({length:42},(_,i)=>{const day=new Date(+first+i*86400000).toISOString().slice(0,10);return {day,number:Number(day.slice(-2)),current:day.startsWith(calendarMonth.value),events:rows.value.filter(r=>r.dueAt&&crmDay(new Date(r.dueAt))===day)}})})
async function run(work:()=>Promise<void>){if(saving.value)return;saving.value=true;error.value='';notice.value='';try{await work()}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'CRM request failed.'}finally{saving.value=false}}
async function bootstrap(){boot.value=await api('bootstrap');if(props.section==='segments'&&typeof route.query.segmentKey==='string'){segmentKey.value=route.query.segmentKey;const segment=settings.value.segments.find((s:any)=>s.key===segmentKey.value);if(segment)filter.value={archived:'false',...segment.filters}};if(!filter.value.pipelineKey)filter.value.pipelineKey=settings.value.pipelines[0]?.key||''}
async function load(){const token=++requestVersion;loading.value=true;error.value='';try{
  if(!boot.value)await bootstrap();if(!boot.value.ready)return
  if(['settings','reports','funnel','campaigns'].includes(props.section)&&!canManage.value){error.value='This page requires a company administrator or manager.';return}
  if(props.recordId&&kind.value)detail.value=await api(kind.value+'/'+props.recordId)
  else if(props.section==='overview')summary.value=await api('summary')
  else if(['reports','funnel'].includes(props.section))reports.value=await api('reports',{query:reportDates.value})
  else if(kind.value){const query:any={...filter.value,page:page.value,pageSize:pageSize.value}
    if(props.section==='calendar'){query.from=calendarDays.value[0].day;query.to=calendarDays.value[41].day;query.status='';query.page=1}
    const result=await api(kind.value,{query});if(token!==requestVersion||disposed)return;rows.value=result.rows;total.value=result.total;selected.value=[]
    if(props.section==='calendar')while(rows.value.length<result.total&&rows.value.length<5000){query.page++;const next=await api('activities',{query});if(token!==requestVersion||disposed)return;if(!next.rows.length)break;rows.value.push(...next.rows)}
  }
}catch(e:any){if(token===requestVersion&&!disposed)error.value=e?.data?.statusMessage||e.message||'Could not load CRM data.'}finally{if(token===requestVersion&&!disposed)loading.value=false}}
function search(){page.value=1;void load()}
function addTask(row:any={}){openEditor('activities',{kind:'TASK',...(kind.value==='clients'&&row.id?{clientId:row.clientId||row.id,clientName:row.name}:kind.value==='deals'&&row.id?{dealId:row.id,dealName:row.name,clientId:row.clientId,clientName:row.clientName,accountId:row.accountId}:{}),...(props.section==='segments'&&settings.value.segments.some((s:any)=>s.key===segmentKey.value)?{segmentKey:segmentKey.value}:{})})}
function openEditor(type:CrmKind,row:any={}){if(type==='clients'&&!row.id)return;editorKind.value=type;editor.value={...row}}
async function saved(){editor.value=null;notice.value='Record saved.';await load()}
async function moveDeal(id:string,stageKey:string){const row=rows.value.find(r=>r.id===id),stage=pipeline.value.stages.find((s:any)=>s.key===stageKey);if(!row||!canEdit(row)||row.stageKey===stageKey)return
  if(stage?.status==='LOST'){openEditor('deals',{...row,stageKey});return}await run(async()=>{await api('deals/'+id,{method:'PUT',body:{...row,stageKey,pipelineKey:pipeline.value.key}});await load();notice.value='Deal stage updated.'})}
async function activityState(row:any,status:string){await run(async()=>{await api('activities/'+row.id,{method:'PUT',body:{...row,status}});await load();notice.value=status==='DONE'?'Activity completed.':'Activity updated.'})}
async function bulk(action:string,archived=false){if(!kind.value||!selectedRows.value.length)return;await run(async()=>{await api(kind.value+'/bulk',{method:'POST',body:{action,archived,ownerId:bulkOwner.value,records:selectedRows.value.map(r=>({id:r.id,version:r.version}))}});await load();notice.value='Selected records updated.'})}
async function archiveOne(row:any){if(!kind.value)return;await run(async()=>{await api(kind.value+'/bulk',{method:'POST',body:{action:'archive',archived:!row.archived,records:[{id:row.id,version:row.version}]}});await load();notice.value=row.archived?'Record restored.':'Record archived; its history is retained.'})}
async function exportRows(){if(!kind.value)return;await run(async()=>{const response=await scope.fetch.raw('/api/crm/'+kind.value+'/export',{query:{...filter.value},responseType:'text',retry:0});const blob=new Blob([String(response._data)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='crm-'+kind.value+'.csv';a.click();URL.revokeObjectURL(url);notice.value=response.headers.get('X-CRM-Export-Truncated')==='true'?'Exported the first 5,000 matches. Narrow the filters to export another set.':'CSV downloaded.'})}
function downloadImportTemplate(){const columns:[string,string][]=['clientId','name','email','phone','source','lifecycle','leadStatus','tags',...settings.value.customFields.map((field:any)=>'custom:'+field.label)].map(label=>[label,label]);const data=crmCsv([],columns),url=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'})),anchor=document.createElement('a');anchor.href=url;anchor.download='crm-client-attributes-template.csv';anchor.click();URL.revokeObjectURL(url)}
async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>2_000_000){error.value='CSV files must be smaller than 2 MB.';return}importText.value=await file.text();preview.value=null}
async function previewImport(){await run(async()=>{importRows.value=parseCrmCsv(importText.value);preview.value=await api('clients/import',{method:'POST',body:{records:importRows.value,preview:true}})})}
async function commitImport(){await run(async()=>{const result=await api('clients/import',{method:'POST',body:{records:importRows.value}});importing.value=false;preview.value=null;await load();notice.value=result.count+' client CRM records updated.'})}
async function findDocuments(){await run(async()=>{documentChoices.value=await api('documents',{query:{kind:documentKind.value,q:documentSearch.value,clientId:detail.value?.record?.linkedClientId||''}})})}
async function addDocument(){await run(async()=>{await api('deals/'+props.recordId+'/documents',{method:'POST',body:{kind:documentKind.value,documentId:documentId.value}});documentPanel.value=false;await load();notice.value='Document linked.'})}
async function saveSegment(){await run(async()=>{if(!segmentName.value.trim())throw Error('Enter a segment name.');const value=JSON.parse(JSON.stringify(settings.value));value.segments.push({key:'segment_'+Date.now().toString(36),name:segmentName.value.trim(),filters:{...filter.value,lifecycle:filter.value.lifecycle||undefined}});await api('settings',{method:'PUT',body:{settings:value,version:boot.value.version}});segmentName.value='';await bootstrap();notice.value='Segment saved. It will use the latest matching clients.'})}
function selectSegment(){const item=settings.value.segments.find((s:any)=>s.key===segmentKey.value);filter.value={archived:'false',...(item?.filters||{})};search()}
async function removeSegment(){await run(async()=>{const value=JSON.parse(JSON.stringify(settings.value));value.segments=value.segments.filter((s:any)=>s.key!==segmentKey.value);await api('settings',{method:'PUT',body:{settings:value,version:boot.value.version}});segmentKey.value='';await bootstrap();notice.value='Segment removed.'})}
function monthChange(amount:number){const date=new Date(calendarMonth.value+'-01T12:00:00Z');date.setUTCMonth(date.getUTCMonth()+amount);calendarMonth.value=date.toISOString().slice(0,7);void load()}
const statusLabel=(value:string)=>String(value||'').replaceAll('_',' ')
onMounted(load)
onBeforeUnmount(()=>{disposed=true;requestVersion++;scope.busy.value=false})
</script>
<template><UDashboardPanelContent class="crm-workspace pb-20">
  <CompanyFormField v-if="!embedded" toolbar :locked="locked"/>
  <header class="mb-6 flex flex-wrap items-start justify-between gap-3"><div><p class="mb-1 text-xs font-semibold uppercase tracking-wider text-primary-600 dark:text-primary-400">Customer relationships</p><h1 class="text-2xl font-semibold">{{title}}</h1><p class="mt-1 text-sm text-gray-500">{{recordId?'Contact context, conversations and connected work.':section==='overview'?'Your pipeline, follow-ups and team activity in one place.':section==='clients'?'A company-wide directory with client and service history.':section==='deals'?'Move opportunities from enquiry to won business.':'Manage your company’s relationships and follow-ups.'}}</p></div><div class="flex flex-wrap gap-2"><UButton color="gray" variant="ghost" icon="i-heroicons-arrow-path" :loading="loading" :disabled="saving" @click="boot=null;load()">Refresh</UButton><UButton v-if="boot?.ready&&!recordId&&['clients','deals','segments'].includes(section)" color="gray" icon="i-heroicons-plus" :disabled="saving" @click="addTask()">Add task</UButton><UButton v-if="kind&&kind!=='clients'&&boot?.ready&&!recordId" icon="i-heroicons-plus" :disabled="saving" @click="openEditor(kind)">{{kind==='accounts'?'New account':kind==='deals'?'New deal':'New activity'}}</UButton><UButton v-if="kind==='clients'&&!recordId" :to="{path:'/client',query:{from:'crm',entryCompany:scope.companyId.value}}" icon="i-heroicons-user-plus">Add / manage clients</UButton></div></header>
  <p v-if="error" role="alert" class="crm-error mb-4">{{error}}</p><p v-if="notice" role="status" class="crm-success mb-4">{{notice}}</p>
  <div v-if="!boot&&loading" role="status" class="crm-panel">Loading your CRM…</div>
  <section v-if="boot&&!boot.ready" class="crm-panel space-y-3"><h2 class="font-semibold">CRM setup is pending</h2><p class="text-sm text-gray-500">Your CRM workspace is ready for installation. An administrator needs to complete the database update before records can be saved.</p><UButton :to="link('/client')" color="gray">Open existing clients</UButton></section>
  <template v-if="boot?.ready">
    <template v-if="section==='overview'&&summary"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NuxtLink v-for="card in [{label:'Active leads',value:summary.clients.leads,to:'/client',icon:'i-heroicons-user-plus'},{label:'Open deal value',value:money(summary.deals.pipelineValue),to:'/crm/deals',icon:'i-heroicons-currency-rupee'},{label:'Weighted forecast',value:money(summary.deals.forecast),to:'/crm/deals',icon:'i-heroicons-chart-bar'},{label:'Overdue activities',value:summary.tasks.overdue,to:'/crm/activities',icon:'i-heroicons-clock'}]" :key="card.label" :to="link(card.to)" class="crm-panel hover:border-primary-400"><UIcon :name="card.icon" class="mb-3 h-5 w-5 text-primary-500"/><p class="text-sm text-gray-500">{{card.label}}</p><p class="mt-1 text-2xl font-semibold">{{card.value}}</p></NuxtLink></div>
      <div class="mt-5 grid gap-5 xl:grid-cols-2"><section class="crm-panel"><h2 class="mb-4 font-semibold">Next actions</h2><div v-for="row in summary.upcoming" :key="row.id" class="flex items-start justify-between gap-3 border-b border-gray-100 py-3 dark:border-gray-800"><div><p class="font-medium">{{row.subject}}</p><p class="text-xs text-gray-500">{{row.clientName}} · {{time(row.dueAt)}}</p></div><UButton v-if="canEdit(row)" color="gray" variant="ghost" @click="openEditor('activities',row)">Open</UButton></div><p v-if="!summary.upcoming.length" class="crm-help">No open follow-ups. Add a lead or create your first activity.</p><UButton :to="link('/crm/activities')" variant="link" class="mt-3">All activities</UButton></section><section class="crm-panel"><h2 class="mb-4 font-semibold">Recent changes</h2><div v-for="row in summary.recent" :key="row.id" class="border-b border-gray-100 py-3 dark:border-gray-800"><p class="text-sm">{{row.summary}}</p><p class="mt-1 text-xs text-gray-500">{{time(row.createdAt)}}</p></div><p v-if="!summary.recent.length" class="crm-help">Your team’s saved changes will appear here.</p></section></div>
      <div class="mt-5 flex flex-wrap gap-2"><UButton color="gray" @click="openEditor('clients')">Add a lead</UButton><UButton color="gray" @click="openEditor('deals')">Create a deal</UButton><UButton :to="link('/crm/calendar')" color="gray">Open calendar</UButton><UButton v-if="boot.workflow?.includeAfterSales" :to="link('/after-sales')" color="gray">After-sales workspace</UButton></div>
    </template>
    <template v-if="recordId&&detail&&kind"><div class="mb-4 flex flex-wrap gap-2"><UButton v-if="!embedded" :to="kind==='clients'?{path:'/client',query:{from:'crm',entryCompany:scope.companyId.value}}:link('/crm/'+kind)" color="gray" variant="ghost">Back to list</UButton><UButton v-if="canEdit(detail.record)" @click="openEditor(kind,detail.record)">{{kind==='clients'?'Edit CRM attributes':'Edit record'}}</UButton><UButton v-if="!detail.record.archived" color="gray" @click="addTask(detail.record)">Add task</UButton><UButton v-if="!detail.record.archived" color="gray" @click="openEditor('activities',{clientId:kind==='clients'?recordId:detail.record.clientId,accountId:kind==='accounts'?recordId:detail.record.accountId,dealId:kind==='deals'?recordId:''})">Add activity</UButton><UButton v-if="kind==='clients'&&boot.workflow?.includeAfterSales" :to="link('/after-sales/customers/'+recordId)" color="gray">Service history</UButton><UButton v-if="kind==='clients'" :to="{path:'/client',query:{from:'crm',entryCompany:scope.companyId.value}}" color="gray">Client directory</UButton><UButton v-if="kind==='deals'&&canEdit(detail.record)" color="gray" @click="documentPanel=true;findDocuments()">Link sales document</UButton><UButton v-if="canManage&&kind!=='clients'" color="gray" @click="archiveOne(detail.record)">{{detail.record.archived?'Restore':'Archive'}}</UButton></div>
      <div class="grid gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(280px,2fr)]"><section class="crm-panel space-y-4"><p class="crm-help">Owner: {{detail.record.ownerName||'Team member'}} · Updated {{time(detail.record.updatedAt)}}</p><NuxtLink v-if="detail.record.accountId" :to="recordLink('accounts',detail.record.accountId)" class="block text-sm text-primary-600">{{detail.record.accountName||'Business account'}}</NuxtLink><NuxtLink v-if="kind!=='clients'&&detail.record.clientId" :to="recordLink('clients',detail.record.clientId)" class="block text-sm text-primary-600">{{detail.record.clientName||'Contact'}}</NuxtLink><p v-if="detail.record.archived" class="text-sm text-amber-600">Archived; history is retained.</p><template v-if="kind==='clients'"><p class="text-sm">{{statusLabel(detail.record.lifecycle)}} · {{statusLabel(detail.record.leadStatus)}}</p><p class="text-2xl font-semibold">{{detail.record.score}} <span class="text-sm font-normal text-gray-500">lead score</span></p><p v-if="detail.record.email"><a :href="'mailto:'+detail.record.email" class="text-primary-600">{{detail.record.email}}</a></p><p v-if="detail.record.phone"><a :href="'tel:'+detail.record.phone" class="text-primary-600">{{detail.record.phone}}</a></p><a v-if="/^\+[1-9]\d{7,14}$/.test(detail.record.phone||'')" :href="'https://wa.me/'+detail.record.phone.slice(1)" target="_blank" rel="noopener noreferrer" class="inline-block text-sm text-primary-600">Open WhatsApp ↗</a><UButton v-if="canManage" :to="{path:'/connect/whatsapp',query:{entryCompany:scope.companyId.value,tab:'Notifications'}}" color="gray" variant="link">Manage WhatsApp permissions</UButton><p class="text-sm">{{detail.record.jobTitle}}</p><p class="crm-help">Source: {{detail.record.source}}</p><div v-if="detail.commerce.client" class="rounded-lg bg-gray-50 p-3 dark:bg-gray-800"><p class="text-sm font-medium">Linked client: {{detail.commerce.client.name}}</p><p class="crm-help">{{detail.commerce.client.phone}} · {{detail.commerce.client.email}}</p><p class="crm-help">Points: {{detail.commerce.client.points}} · {{detail.commerce.client.status?'Active':'Inactive'}}</p><p class="mt-2 text-xs">Email subscription: {{detail.commerce.permissions?.emailConfirmed?'Confirmed for the current address':'Not confirmed'}}</p><p class="mt-1 text-xs">WhatsApp: {{!detail.commerce.permissions?.whatsappAvailable?'Permission setup pending':detail.commerce.permissions.whatsappService?'Service updates allowed':'Service updates off'}} · {{detail.commerce.permissions?.whatsappMarketing?'Marketing allowed':'Marketing off'}}</p></div><div v-for="field in settings.customFields" :key="field.key" class="text-sm"><span class="text-gray-500">{{field.label}}:</span> {{detail.record.customFields?.[field.key]??'—'}}</div></template>
          <template v-if="kind==='accounts'"><p>{{detail.record.industry}}</p><p class="text-sm">{{detail.record.email}}</p><p class="text-sm">{{detail.record.phone}}</p><p class="whitespace-pre-wrap text-sm">{{detail.record.address}}</p><a v-if="detail.record.website" :href="detail.record.website" target="_blank" rel="noopener noreferrer" class="text-sm text-primary-600">Visit website ↗</a></template>
          <template v-if="kind==='deals'"><p class="text-3xl font-semibold">{{money(detail.record.value)}}</p><p class="text-sm">{{statusLabel(detail.record.status)}} · {{detail.record.probability}}% probability</p><p class="crm-help">Expected close: {{date(detail.record.expectedClose)}}</p><p v-if="detail.record.lossReason" class="text-sm">Loss reason: {{detail.record.lossReason}}</p></template><p class="whitespace-pre-wrap text-sm">{{detail.record.description}}</p><div class="flex flex-wrap gap-1"><span v-for="tag in detail.record.tags" :key="tag" class="crm-badge">{{tag}}</span></div>
        </section><section class="space-y-5"><div class="crm-panel"><h2 class="mb-4 font-semibold">Activities and notes</h2><article v-for="row in detail.activities" :key="row.id" class="border-b border-gray-100 py-3 dark:border-gray-800"><div class="flex justify-between gap-2"><p class="font-medium">{{row.subject}}</p><button v-if="canEdit(row)" class="text-sm text-primary-600" @click="openEditor('activities',row)">Edit</button></div><p class="crm-help">{{row.kind}} · {{statusLabel(row.status)}} · {{time(row.dueAt||row.createdAt)}}</p><p class="mt-2 whitespace-pre-wrap text-sm">{{row.body}}</p><a v-for="item in row.attachments||[]" :key="item.url" :href="item.url" target="_blank" rel="noopener noreferrer" class="mr-3 text-sm text-primary-600">{{item.name}} ↗</a></article><p v-if="!detail.activities.length" class="crm-help">No activities logged yet.</p></div>
          <section v-if="detail.clients.length" class="crm-panel"><h2 class="mb-3 font-semibold">Account clients</h2><NuxtLink v-for="row in detail.clients" :key="row.id" :to="recordLink('clients',row.id)" class="block py-2 text-sm text-primary-600">{{row.name}} · {{row.email||row.phone}}</NuxtLink></section>
          <section v-if="detail.deals.length" class="crm-panel"><h2 class="mb-3 font-semibold">Related deals</h2><NuxtLink v-for="row in detail.deals" :key="row.id" :to="recordLink('deals',row.id)" class="flex justify-between py-2 text-sm"><span class="text-primary-600">{{row.name}}</span><span>{{money(row.value)}} · {{row.status}}</span></NuxtLink></section>
          <section v-if="detail.documents.length" class="crm-panel"><h2 class="mb-3 font-semibold">Linked documents</h2><div v-for="row in detail.documents" :key="row.id"><button v-if="row.kind==='ORDER'" class="py-2 text-sm text-primary-600" @click="showOrder(row.documentId)">ORDER · View order</button><NuxtLink v-else :to="link(row.kind==='QUOTE'?'/erp/quotes/edit/'+row.documentId:row.kind==='SALES_ORDER'?'/erp/sales-orders/edit/'+row.documentId:'/erp/edit/'+row.documentId)" class="block py-2 text-sm text-primary-600">{{row.kind}} · Open document ↗</NuxtLink></div></section>
          <template v-if="kind==='clients'&&detail.commerce.client"><section v-for="group in ['bills','quotes','orders','products'].filter(group=>group!=='products'||boot.workflow?.includeAfterSales)" :key="group" class="crm-panel"><h2 class="mb-3 font-semibold capitalize">{{group==='bills'?'Invoices and sales':group==='products'?'Registered products':group}}</h2><div v-for="row in detail.commerce[group]" :key="row.id" class="flex items-center justify-between gap-3 border-b border-gray-100 py-2 text-sm dark:border-gray-800"><button v-if="group==='orders'" class="text-primary-600" @click="showOrder(row.id)">{{row.number||'View order'}}</button><NuxtLink v-else :to="link(group==='bills'?'/erp/edit/'+row.id:group==='quotes'?'/erp/quotes/edit/'+row.id:'/after-sales/products/'+row.id)" class="text-primary-600">{{row.number||row.reference||row.name||'Open record'}}</NuxtLink><span>{{row.total!=null?money(row.total):''}} {{row.status}}</span></div><p v-if="!detail.commerce[group].length" class="crm-help">No linked records.</p></section><section v-if="detail.commerce.legacyActivities.length" class="crm-panel"><h2 class="mb-3 font-semibold">Earlier storefront notes</h2><div v-for="row in detail.commerce.legacyActivities" :key="row.id" class="border-b py-2 text-sm"><p>{{row.kind}} · {{time(row.createdAt)}}</p><p class="whitespace-pre-wrap">{{row.body}}</p></div></section></template>
          <section class="crm-panel"><h2 class="mb-3 font-semibold">Change history</h2><div v-for="row in detail.audit" :key="row.id" class="border-b border-gray-100 py-2 text-sm dark:border-gray-800"><p>{{row.summary}} · {{row.actorName||'Team member'}}</p><p class="crm-help">{{time(row.createdAt)}}</p></div><p v-if="!detail.audit.length" class="crm-help">No changes recorded.</p></section>
        </section></div>
    </template>
    <template v-if="kind&&!recordId"><div v-if="section==='segments'" class="crm-panel mb-4 space-y-3"><h2 class="font-semibold">Saved contact segments</h2><p class="crm-help">Segments are saved filters. Their members update as contact details change; saving a segment does not grant marketing permission.</p><div class="flex flex-wrap gap-2"><select v-model="segmentKey" class="crm-input max-w-xs" aria-label="Saved segment" @change="selectSegment"><option value="">Choose a saved segment</option><option v-for="item in settings.segments" :key="item.key" :value="item.key">{{item.name}}</option></select><button v-if="segmentKey&&settings.segments.some((s:any)=>s.key===segmentKey)" class="crm-button" @click="addTask()">Add task for segment</button><NuxtLink v-if="segmentKey" :to="{path:'/crm/activities',query:{entryCompany:scope.companyId.value,segmentKey}}" class="crm-button">View segment tasks</NuxtLink><button v-if="canManage&&segmentKey" class="crm-button" @click="removeSegment">Remove segment</button><input v-if="canManage" v-model="segmentName" class="crm-input max-w-xs" placeholder="New segment name" aria-label="Segment name"/><button v-if="canManage" class="crm-button" :disabled="saving" @click="saveSegment">Save current filters</button></div></div>
      <form class="mb-4 flex flex-wrap items-end gap-2" @submit.prevent="search"><label class="crm-label flex-1 min-w-[180px]">Search<input v-model="filter.q" class="crm-input" placeholder="Name, email, phone or description"/></label><label class="crm-label">Owner<select v-model="filter.ownerId" class="crm-input"><option value="">All owners</option><option v-for="member in boot.staff" :key="member.id" :value="member.id">{{member.name}}</option></select></label><label v-if="kind==='clients'" class="crm-label">Source<select v-model="filter.source" class="crm-input"><option value="">All sources</option><option v-for="item in settings.sources" :key="item" :value="item">{{item}}</option></select></label><label v-if="kind==='clients'" class="crm-label">Type<select v-model="filter.lifecycle" class="crm-input"><option value="">All clients</option><option value="LEAD">Leads</option><option value="CONTACT">Contacts</option><option value="CUSTOMER">Customers</option></select></label><label v-if="kind==='clients'" class="crm-label">Qualification<select v-model="filter.leadStatus" class="crm-input"><option value="">All</option><option v-for="state in ['NEW','CONTACTED','QUALIFIED','UNQUALIFIED']" :key="state" :value="state">{{state}}</option></select></label><label v-if="kind==='clients'" class="crm-label">Minimum score<input v-model="filter.minScore" class="crm-input w-24" type="number" min="0" max="100"/></label><label v-if="kind==='deals'" class="crm-label">Pipeline<select v-model="filter.pipelineKey" class="crm-input" @change="search"><option v-for="item in settings.pipelines" :key="item.key" :value="item.key">{{item.name}}</option></select></label><label v-if="kind==='activities'" class="crm-label">Segment<select v-model="filter.segmentKey" class="crm-input"><option value="">All segments</option><option v-for="item in settings.segments" :key="item.key" :value="item.key">{{item.name}}</option></select></label><label v-if="kind==='deals'||kind==='activities'" class="crm-label">Status<select v-model="filter.status" class="crm-input"><option value="">All</option><option v-for="item in kind==='deals'?['OPEN','WON','LOST']:['OPEN','DONE','CANCELLED']" :key="item" :value="item">{{item}}</option></select></label><label v-if="kind!=='activities'" class="crm-label">Tag<input v-model="filter.tag" class="crm-input w-36" list="crm-filter-tags" placeholder="Any tag"/><datalist id="crm-filter-tags"><option v-for="tag in settings.tags" :key="tag" :value="tag"/></datalist></label><label v-if="kind==='activities'" class="crm-label">Due<select v-model="filter.due" class="crm-input"><option value="">Any time</option><option value="OVERDUE">Overdue</option><option value="TODAY">Today</option><option value="NEXT7">Next 7 days</option></select></label><label v-if="kind==='activities'" class="crm-label">Priority<select v-model="filter.priority" class="crm-input"><option value="">All</option><option v-for="priority in ['LOW','NORMAL','HIGH']" :key="priority" :value="priority">{{priority}}</option></select></label><label class="crm-label">Records<select v-model="filter.archived" class="crm-input"><option value="false">Active</option><option value="true">Archived</option><option value="all">All records</option></select></label><button class="crm-button" :disabled="loading">Apply filters</button></form>
      <div class="mb-4 flex flex-wrap justify-between gap-2"><p class="text-sm text-gray-500">{{total}} {{kind}}<span v-if="section==='calendar'"> · Times shown in India time</span></p><div class="flex flex-wrap gap-2"><UButton v-if="kind==='deals'" color="gray" size="xs" @click="view=view==='board'?'table':'board';page=1;load()">{{view==='board'?'Table view':'Pipeline view'}}</UButton><UButton v-if="kind==='clients'" color="gray" size="xs" @click="importing=true;preview=null">Import CSV</UButton><UButton color="gray" size="xs" :disabled="saving" @click="exportRows">Export CSV</UButton></div></div>
      <div v-if="canManage&&selected.length" class="mb-4 flex flex-wrap items-center gap-2 rounded-lg bg-primary-50 p-3 dark:bg-primary-950"><span class="text-sm">{{selected.length}} selected</span><select v-model="bulkOwner" class="crm-input max-w-xs" aria-label="New owner"><option value="">Choose new owner</option><option v-for="member in boot.staff" :key="member.id" :value="member.id">{{member.name}}</option></select><button class="crm-button" :disabled="saving||!bulkOwner" @click="bulk('assign')">Assign owner</button><button class="crm-button" :disabled="saving" @click="bulk('archive',filter.archived!=='true')">{{filter.archived==='true'?'Restore selected':'Archive selected'}}</button></div>
      <div v-if="section==='calendar'" class="crm-panel"><div class="mb-4 flex flex-wrap items-center justify-between gap-2"><UButton color="gray" aria-label="Previous month" @click="monthChange(-1)">←</UButton><label class="crm-label">Month<input v-model="calendarMonth" class="crm-input" type="month" @change="load"/></label><UButton color="gray" aria-label="Next month" @click="monthChange(1)">→</UButton></div><p v-if="total>rows.length" class="mb-3 text-sm text-amber-600">Showing {{rows.length}} of {{total}} activities. Narrow the owner filter for a complete calendar.</p><div class="overflow-x-auto"><div class="grid min-w-[700px] grid-cols-7"><p v-for="day in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day" class="border p-2 text-center text-xs font-semibold dark:border-gray-700">{{day}}</p><div v-for="day in calendarDays" :key="day.day" class="min-h-24 border p-2 dark:border-gray-700" :class="{'bg-gray-50 text-gray-400 dark:bg-gray-900':!day.current,'bg-primary-50 dark:bg-primary-950':day.day===crmDay()}"><p class="text-xs font-medium">{{day.number}}</p><button v-for="row in day.events" :key="row.id" class="mt-1 block w-full rounded bg-primary-100 p-1 text-left text-xs text-primary-800 dark:bg-primary-900 dark:text-primary-200" @click="openEditor('activities',row)">{{row.subject}} · {{row.status}}</button></div></div></div></div>
      <div v-else-if="kind==='deals'&&view==='board'" class="overflow-x-auto pb-3"><div class="flex min-w-max items-start gap-4"><section v-for="stage in pipeline.stages" :key="stage.key" class="w-72 rounded-xl bg-gray-100 p-3 dark:bg-gray-800/60" @dragover.prevent @drop.prevent="moveDeal(dragId,stage.key)"><div class="mb-3 flex items-center justify-between gap-2"><h2 class="text-sm font-semibold">{{stage.name}}</h2><span class="crm-badge">{{rows.filter(row=>row.stageKey===stage.key).length}}</span></div><article v-for="row in rows.filter(row=>row.stageKey===stage.key)" :key="row.id" class="mb-3 rounded-lg border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900" :draggable="canEdit(row)" @dragstart="dragId=row.id"><NuxtLink :to="recordLink('deals',row.id)" class="font-medium hover:text-primary-600">{{row.name}}</NuxtLink><p class="mt-2 text-lg font-semibold">{{money(row.value)}}</p><p class="mt-1 text-xs text-gray-500">{{row.clientName||row.accountName||'No linked contact'}} · {{row.ownerName||'Team member'}}</p><p class="mt-1 text-xs text-gray-500">Close {{date(row.expectedClose)}}</p><button class="mt-3 mr-3 text-sm text-primary-600" @click="addTask(row)">Add task</button><button v-if="canEdit(row)" class="mt-3 text-sm text-primary-600" @click="openEditor('deals',row)">Edit deal</button><button v-if="canEdit(row)" class="mt-3 text-xs font-medium text-primary-600" @click="openEditor('deals',row)">Edit / change stage</button></article><p v-if="!rows.some(row=>row.stageKey===stage.key)" class="py-5 text-center text-xs text-gray-500">No deals on this page</p></section></div></div>
      <div v-else class="overflow-x-auto rounded-xl border border-gray-200 dark:border-gray-700"><table class="crm-table"><thead><tr><th v-if="canManage"><input :checked="allSelected" type="checkbox" aria-label="Select all shown records" @change="selected=allSelected?[]:rows.map(row=>row.id)"/></th><th>{{kind==='activities'?'Activity':kind==='accounts'?'Business account':'Name'}}</th><th>{{kind==='clients'?'Type / qualification':kind==='deals'?'Stage':kind==='activities'?'Status':'Industry'}}</th><th>Owner</th><th>{{kind==='deals'?'Value':kind==='clients'?'Score':kind==='activities'?'Due':'Contact'}}</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td v-if="canManage"><input v-model="selected" :value="row.id" type="checkbox" :aria-label="'Select '+(row.name||row.subject)"/></td><td><button v-if="kind==='activities'" class="text-left font-medium text-primary-600" @click="openEditor('activities',row)">{{row.subject}}</button><NuxtLink v-else :to="recordLink(kind,row.id)" class="font-medium text-primary-600">{{row.name}}</NuxtLink><p class="mt-1 text-xs text-gray-500">{{row.email||row.clientName||row.accountName||row.kind}} {{row.phone}}</p><NuxtLink v-if="row.segmentKey" :to="{path:'/crm/segments',query:{entryCompany:scope.companyId.value,segmentKey:row.segmentKey}}" class="text-xs text-primary-600">Segment: {{row.segmentName||'Removed segment'}}</NuxtLink><span v-for="tag in row.tags||[]" :key="tag" class="crm-badge mr-1 mt-1">{{tag}}</span></td><td><span class="crm-badge">{{kind==='clients'?statusLabel(row.lifecycle)+' · '+statusLabel(row.leadStatus):kind==='accounts'?row.industry||'—':kind==='deals'?settings.pipelines.find((p:any)=>p.key===row.pipelineKey)?.stages.find((s:any)=>s.key===row.stageKey)?.name||row.status:row.status}}</span><p v-if="row.archived" class="mt-1 text-xs text-amber-600">Archived</p></td><td>{{row.ownerName||boot.staff.find((member:any)=>member.id===row.ownerId)?.name||'Former team member'}}</td><td><span v-if="kind==='deals'">{{money(row.value)}}</span><span v-else-if="kind==='clients'" :class="row.score>=60?'font-semibold text-emerald-600':''">{{row.score}} / 100</span><span v-else-if="kind==='activities'" :class="row.status==='OPEN'&&row.dueAt&&new Date(row.dueAt)<new Date()?'text-red-600':''">{{time(row.dueAt)}}</span><span v-else>{{row.email||row.phone||'—'}}</span></td><td><div class="flex gap-2"><button v-if="kind==='clients'||kind==='deals'" class="text-sm text-primary-600" @click="addTask(row)">Add task</button><button v-if="canEdit(row)" class="text-sm text-primary-600" @click="openEditor(kind,row)">Edit</button><button v-if="kind==='activities'&&row.status==='OPEN'&&canEdit(row)" class="text-sm text-emerald-600" @click="activityState(row,'DONE')">Complete</button><button v-if="canManage&&kind!=='clients'" class="text-sm text-gray-500" @click="archiveOne(row)">{{row.archived?'Restore':'Archive'}}</button></div></td></tr></tbody></table><p v-if="!rows.length&&!loading" class="p-8 text-center text-sm text-gray-500">No matching {{kind}}. Add a record or adjust the filters.</p><p v-if="loading" role="status" class="p-5 text-sm text-gray-500">Loading records…</p></div>
      <div v-if="section!=='calendar'" class="mt-4 flex items-center justify-between gap-3"><p class="text-xs text-gray-500">Page {{page}} of {{Math.max(1,Math.ceil(total/pageSize))}} · {{rows.length}} shown</p><div class="flex gap-2"><UButton color="gray" :disabled="loading||page===1" @click="page--;load()">Previous</UButton><UButton color="gray" :disabled="loading||page*pageSize>=total" @click="page++;load()">Next</UButton></div></div>
    </template>
    <Settings v-if="section==='settings'&&canManage" :key="boot.version" :value="settings" :version="boot.version" :company-id="scope.companyId.value" @saved="bootstrap" @busy="value=>saving=value"/>
    <Campaigns v-if="section==='campaigns'&&canManage" :company-id="scope.companyId.value" :ready="boot.marketingReady" @busy="value=>saving=value"/>
    <template v-if="section==='funnel'&&canManage">
      <form class="mb-5 flex flex-wrap items-end gap-3" @submit.prevent="load"><label class="crm-label">Deals created from<input v-model="reportDates.from" class="crm-input" type="date"/></label><label class="crm-label">Deals created through<input v-model="reportDates.to" class="crm-input" type="date"/></label><button class="crm-button" :disabled="loading">Update funnel</button></form>
      <Funnel v-if="reports&&!error" :aria-busy="loading" :settings="settings" :rows="reports.pipeline" :currency="boot.currency"/>
      <p v-if="loading" role="status" class="crm-panel">Loading funnel...</p>
    </template>
    <template v-if="section==='reports'&&canManage"><form class="mb-5 flex flex-wrap items-end gap-3" @submit.prevent="load"><label class="crm-label">Created from<input v-model="reportDates.from" class="crm-input" type="date"/></label><label class="crm-label">Created through<input v-model="reportDates.to" class="crm-input" type="date"/></label><button class="crm-button" :disabled="loading">Update reports</button></form><p class="mb-4 text-sm text-gray-500">Deal forecasts use saved probability and company currency. Won value is a CRM outcome; invoiced and collected amounts remain in sales/accounts reports.</p><div v-if="reports" class="grid gap-5 xl:grid-cols-2"><section class="crm-panel"><h2 class="mb-4 font-semibold">Pipeline and stage aging</h2><div v-for="row in reports.pipeline" :key="row.pipelineKey+row.stageKey" class="mb-4"><div class="flex justify-between text-sm"><span>{{settings.pipelines.find((p:any)=>p.key===row.pipelineKey)?.stages.find((s:any)=>s.key===row.stageKey)?.name||row.stageKey}} · {{row.count}} deals</span><span>{{money(row.value)}}</span></div><div class="mt-2 h-2 overflow-hidden rounded bg-gray-100 dark:bg-gray-800"><div class="h-full rounded bg-primary-500" :style="{width:Math.max(2,Number(row.value)/Math.max(1,...reports.pipeline.map((r:any)=>Number(r.value)))*100)+'%'}"/></div><p class="mt-1 text-xs text-gray-500">Average {{row.ageDays||0}} days in stage · weighted {{money(row.weightedValue)}}</p></div><p v-if="!reports.pipeline.length" class="crm-help">No deals in this period.</p></section><section class="crm-panel"><h2 class="mb-4 font-semibold">Forecast by expected close month</h2><div v-for="row in reports.forecast" :key="row.month||'none'" class="flex justify-between border-b py-3 text-sm dark:border-gray-700"><span>{{row.month||'No close date'}}</span><span>{{money(row.weightedValue)}} <span class="text-gray-500">/ {{money(row.value)}}</span></span></div><p v-if="!reports.forecast.length" class="crm-help">No open deal forecast.</p></section><section class="crm-panel overflow-x-auto"><h2 class="mb-4 font-semibold">Team performance</h2><table class="crm-table"><thead><tr><th>Owner</th><th>Won / lost</th><th>Win rate</th><th>Won value</th></tr></thead><tbody><tr v-for="row in reports.owners" :key="row.ownerId"><td>{{row.name}}</td><td>{{row.won}} / {{row.lost}}</td><td>{{row.won+row.lost?Math.round(row.won/(row.won+row.lost)*100):0}}%</td><td>{{money(row.wonValue)}}</td></tr></tbody></table></section><section class="crm-panel"><h2 class="mb-4 font-semibold">Lead source conversion</h2><div v-for="row in reports.sources" :key="row.source" class="flex justify-between border-b py-3 text-sm dark:border-gray-700"><span>{{row.source}}</span><span>{{row.converted}} / {{row.total}} clients · {{row.total?Math.round(row.converted/row.total*100):0}}%</span></div><h3 class="mb-2 mt-5 text-sm font-semibold">Loss reasons</h3><p v-for="row in reports.losses" :key="row.lossReason" class="py-2 text-sm">{{row.lossReason||'Unspecified'}} · {{row.count}} deals · {{money(row.value)}}</p></section></div></template>
  </template>
  <RecordEditor v-if="editor&&boot?.ready" :read-only="!!editor.id&&!canEdit(editor)" :kind="editorKind" :record="editor" :settings="settings" :staff="boot.staff" :company-id="scope.companyId.value" :actor="actor" @close="editor=null" @saved="saved" @busy="value=>saving=value"/>
  <UModal :model-value="importing" :prevent-close="saving" @update:model-value="value=>{if(!saving)importing=value}"><UCard><template #header><h2 class="font-semibold">Update client CRM attributes</h2></template><div class="space-y-4"><p class="crm-help">CSV headers: clientId, name, source, lifecycle, leadStatus, tags. clientId must identify an existing company client. Contact details stay on the client page. Separate tags with semicolons; update up to 200 rows.</p><button type="button" class="crm-button" @click="downloadImportTemplate">Download CSV template</button><p v-if="settings.customFields.length" class="crm-help">Custom fields use custom:Field label columns from the template. Boolean values accept true/false or yes/no.</p><input type="file" accept=".csv,text/csv" aria-label="Contact CSV file" :disabled="saving" @change="readFile"/><label class="crm-label">CSV contents<textarea v-model="importText" class="crm-input font-mono text-xs" rows="8" placeholder="name,email,phone&#10;Alex,alex@example.com,+919876543210" @input="preview=null"/></label><p v-if="preview" class="text-sm">{{preview.valid}} valid / {{preview.total}} rows</p><ul v-if="preview?.errors?.length" class="space-y-1 text-sm text-red-600"><li v-for="item in preview.errors" :key="item.row">Row {{item.row}}: {{item.message}}</li></ul><p v-if="error" role="alert" class="crm-error">{{error}}</p></div><template #footer><div class="flex justify-end gap-2"><UButton color="gray" :disabled="saving" @click="previewImport">Preview import</UButton><UButton :disabled="saving||!preview||preview.errors.length>0" @click="commitImport">Update {{preview?.valid||0}} clients</UButton></div></template></UCard></UModal>

<UModal :model-value="documentPanel" :prevent-close="saving" @update:model-value="value=>{if(!saving)documentPanel=value}"><UCard><template #header><h2 class="font-semibold">Link a sales document</h2></template><div class="space-y-4"><label class="crm-label">Document type<select v-model="documentKind" class="crm-input" @change="documentId='';findDocuments()"><option value="QUOTE">Quotation</option><option value="BILL">Invoice / sale</option><option value="SALES_ORDER">Sales order</option><option value="ORDER">Ecommerce order</option></select></label><div class="flex gap-2"><input v-model="documentSearch" class="crm-input" aria-label="Search sales documents" placeholder="Document number" @keydown.enter.prevent="findDocuments"/><button class="crm-button" :disabled="saving" @click="findDocuments">Search</button></div><label class="crm-label">Document<select v-model="documentId" class="crm-input"><option value="">Select a document</option><option v-for="row in documentChoices" :key="row.id" :value="row.id">{{row.name||'Document'}}</option></select></label><p class="crm-help">Choose a document for the same client as this deal. Linking preserves the document’s current status.</p><p v-if="error" role="alert" class="crm-error">{{error}}</p></div><template #footer><UButton :disabled="saving||!documentId" @click="addDocument">Link document</UButton></template></UCard></UModal>
<UModal :model-value="!!orderPreview" @update:model-value="value=>{if(!value)orderPreview=null}"><UCard v-if="orderPreview"><template #header><h2 class="font-semibold">Order {{orderPreview.number}}</h2></template><div class="space-y-3"><p>{{orderPreview.status}} · {{orderPreview.paymentStatus}}</p><p class="text-xl font-semibold">{{money(orderPreview.total)}}</p><p class="crm-help">Created {{time(orderPreview.createdAt)}}</p><UButton v-if="orderPreview.billId" :to="link('/erp/edit/'+orderPreview.billId)" color="gray">Open invoice / sale</UButton></div></UCard></UModal></UDashboardPanelContent></template>
<style>
.crm-workspace .crm-panel{@apply rounded-xl border border-gray-200 bg-white p-5 dark:border-gray-700 dark:bg-gray-900;}
.crm-label{@apply block space-y-1 text-sm font-medium;}
.crm-input{@apply block w-full min-w-0 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 dark:border-gray-600 dark:bg-gray-900 dark:text-gray-100;}
.crm-button{@apply rounded-md border border-gray-300 px-3 py-2 text-sm font-medium disabled:cursor-not-allowed disabled:opacity-50 dark:border-gray-600;}
.crm-help{@apply text-xs leading-relaxed text-gray-500 dark:text-gray-400;}
.crm-badge{@apply inline-block rounded-md bg-gray-100 px-2 py-1 text-xs text-gray-700 dark:bg-gray-800 dark:text-gray-300;}
